    61  #define yyscan_t void*
    62
    63  int igraph_gml_yylex(YYSTYPE* lvalp, YYLTYPE* llocp, void *scanner);
    64  int igraph_gml_yyerror(YYLTYPE* locp, igraph_i_gml_parsedata_t *context,
    65                         const char *s);
    66  char *igraph_gml_yyget_text (yyscan_t yyscanner );
    67  int igraph_gml_yyget_leng (yyscan_t yyscanner );
    68  void igraph_i_gml_get_keyword(char *s, int len, void *res);
    69  void igraph_i_gml_get_string(char *s, int len, void *res);
    70  double igraph_i_gml_get_real(char *s, int len);
    71  igraph_gml_tree_t *igraph_i_gml_make_numeric(char* s, int len, double value);
    72  igraph_gml_tree_t *igraph_i_gml_make_numeric2(char* s, int len,
    73                                                char *v, int vlen);
    74  igraph_gml_tree_t *igraph_i_gml_make_string(char* s, int len,
    75                                              char *value, int valuelen);
    76  igraph_gml_tree_t *igraph_i_gml_make_list(char* s, int len,
    77                                            igraph_gml_tree_t *list);
    78  igraph_gml_tree_t *igraph_i_gml_merge(igraph_gml_tree_t *t1, igraph_gml_tree_t* t2);
    79
    80  #define scanner context->scanner
    81  #define USE(x) /*(x)*/
    82
    83  %}
    84
    85  %pure-parser
    86  /* bison: do not remove the equals sign; macOS XCode ships with bison 2.3, which
    87   * needs the equals sign */
    88  %name-prefix="igraph_gml_yy"
    89  %defines
    90  %locations
    91  %error-verbose
    92  %parse-param { igraph_i_gml_parsedata_t* context }
    93  %lex-param { void *scanner }
    94
    95  %union {
    96     struct {
    97        char *s;
    98        int len;
    99     } str;
   100     void *tree;
   101     double real;
   102  }
   103
   104  %type <tree>    list;
   105  %type <tree>    keyvalue;
   106  %type <str>     key;
   107  %type <real>    num;
   108  %type <str>     string;
   109
   110  %token STRING
   111  %token NUM
   112  %token <str>    KEYWORD
   113  %token LISTOPEN
   114  %token LISTCLOSE
   115  %token EOFF
   116  %token ERROR
   117
   118  %destructor { igraph_Free($$.s); } string key KEYWORD;
   119  %destructor { igraph_gml_tree_destroy($$); } list keyvalue;
   120
   121  %%
   122
   123  input:   list      { context->tree=$1; }
   124         | list EOFF { context->tree=$1; }
   125  ;
   126
   127  list:   keyvalue      { $$=$1; }
   128        | list keyvalue { $$=igraph_i_gml_merge($1, $2); };
   129
   130  keyvalue:   key num
   131              { $$=igraph_i_gml_make_numeric($1.s, $1.len, $2); }
   132            | key string
   133              { $$=igraph_i_gml_make_string($1.s, $1.len, $2.s, $2.len); }
   134            | key LISTOPEN list LISTCLOSE
   135              { $$=igraph_i_gml_make_list($1.s, $1.len, $3); }
   136            | key key
   137              { $$=igraph_i_gml_make_numeric2($1.s, $1.len, $2.s, $2.len); }
   138  ;
   139
   140  key: KEYWORD { igraph_i_gml_get_keyword(igraph_gml_yyget_text(scanner),
   141                                          igraph_gml_yyget_leng(scanner),
   142                                          &$$); USE($1); };
   143  num : NUM { $$=igraph_i_gml_get_real(igraph_gml_yyget_text(scanner),
   144                                       igraph_gml_yyget_leng(scanner)); };
   145
   146  string: STRING { igraph_i_gml_get_string(igraph_gml_yyget_text(scanner),
   147                                           igraph_gml_yyget_leng(scanner),
   148                                           &$$); };
   149
   150  %%
   151
   152  int igraph_gml_yyerror(YYLTYPE* locp, igraph_i_gml_parsedata_t *context,
   153                         const char *s) {
   154    snprintf(context->errmsg, sizeof(context->errmsg)/sizeof(char)-1,
   155             "Parse error in GML file, line %i (%s)",
   156             locp->first_line, s);
   157    return 0;
   158  }
   159
   160  void igraph_i_gml_get_keyword(char *s, int len, void *res) {
   161    struct { char *s; int len; } *p=res;
   162    p->s=igraph_Calloc(len+1, char);
   163    if (!p->s) {
   164      igraph_error("Cannot read GML file", IGRAPH_FILE_BASENAME, __LINE__, IGRAPH_PARSEERROR);
   165    }
   166    memcpy(p->s, s, sizeof(char)*len);
   167    p->s[len]='\0';
   168    p->len=len;
   169  }
   170
   171  void igraph_i_gml_get_string(char *s, int len, void *res) {
   172    struct { char *s; int len; } *p=res;
   173    p->s=igraph_Calloc(len-1, char);
   174    if (!p->s) {
   175      igraph_error("Cannot read GML file", IGRAPH_FILE_BASENAME, __LINE__, IGRAPH_PARSEERROR);
   176    }
   177    memcpy(p->s, s+1, sizeof(char)*(len-2));
   178    p->s[len-2]='\0';
   179    p->len=len-2;
   180  }
   181
   182  double igraph_i_gml_get_real(char *s, int len) {
   183    igraph_real_t num;
   184    char tmp=s[len];
   185    s[len]='\0';
   186    sscanf(s, "%lf", &num);
   187    s[len]=tmp;
   188    return num;
   189  }
   190
   191  igraph_gml_tree_t *igraph_i_gml_make_numeric(char* s, int len, double value) {
   192    igraph_gml_tree_t *t=igraph_Calloc(1, igraph_gml_tree_t);
   193    if (!t) {
   194      igraph_error("Cannot build GML tree", IGRAPH_FILE_BASENAME, __LINE__, IGRAPH_ENOMEM);
   195      return 0;
   196    }
   197    if (floor(value)==value) {
   198      igraph_gml_tree_init_integer(t, s, len, value);
   199    } else {
   200      igraph_gml_tree_init_real(t, s, len, value);
   201    }
   202
   203    return t;
   204  }
