   206  igraph_gml_tree_t *igraph_i_gml_make_numeric2(char* s, int len,
   207                                                char *v, int vlen) {
   208    igraph_gml_tree_t *t=igraph_Calloc(1, igraph_gml_tree_t);
   209    char tmp=v[vlen];
   210    igraph_real_t value=0;
   211    if (!t) {
   212      igraph_error("Cannot build GML tree", IGRAPH_FILE_BASENAME, __LINE__, IGRAPH_ENOMEM);
   213      return 0;
   214    }
   215    v[vlen]='\0';
   216    if (strcasecmp(v, "inf")) {
   217      value=IGRAPH_INFINITY;
   218    } else if (strcasecmp(v, "nan")) {
   219      value=IGRAPH_NAN;
